for coeff in [[1,-1.2,.4],[1,-1.9048,.9048],[1,-.8],[1,-1.8,.8]]:
    for j,(E,F) in enumerate(dio(coeff,3),1):
        identity=np.convolve(E,coeff)
        identity=np.pad(identity,(0,max(0,j+len(F)-len(identity))))
        identity[j:j+len(F)]+=F
        assert np.max(abs(identity-np.r_[1.,np.zeros(len(identity)-1)]))<1e-12
        print('dio',coeff,'j',j,'E',E,'F',F)
